fn put64(out:[*]u8,pos:*usize,x:i64)void{const u:u64=@bitCast(x);for(0..8)|j|{out[pos.*]=@truncate(u>>(8*j));pos.*+=1;}}
export fn swap_nodes(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<3)return -1;const p=input.?;const nn=p[0];if(nn<0 or nn>64 or length!=@as(usize,@intCast(nn))+3)return -1;const n:usize=@intCast(nn);for(0..n)|i|if(p[1+i]< -2147483648 or p[1+i]>2147483647)return -1;const a=p[1+n];const b=p[2+n];if(a< -2147483648 or a>2147483647 or b< -2147483648 or b>2147483647)return -1;const need=8+8*n;if(output==null or capacity<need)return -2;var ia=n;var ib=n;if(a!=b){for(0..n)|i|{if(ia==n and p[1+i]==a)ia=i;if(ib==n and p[1+i]==b)ib=i;}}const out=output.?;var pos:usize=0;put64(out,&pos,nn);for(0..n)|i|{var x=p[1+i];if(ia<n and ib<n){if(i==ia)x=b else if(i==ib)x=a;}put64(out,&pos,x);}return @intCast(pos);}
